{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C50"],
      "claim": "In healthy volunteers, ipratropium bromide, a quaternary ammonium tropane ester closely analogous to the query, had an absolute oral bioavailability of 3.3% (range 0.9–6.1%) after 20 mg oral versus i.v., directly supporting F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tiotropium bromide, another quaternary ammonium tropane antimuscarinic, showed absolute oral bioavailability of only 2–3% from an oral solution in healthy volunteers, supporting poor oral absorption for this charged tropane class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Ipratropium's low oral bioavailability is partly attributed to active secretion by the intestinal mucosa, a mechanism expected for the permanently charged quaternary ammonium query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium tropane ester (butylscopolamine-like). Closely related quaternary ammonium tropane antimuscarinics ipratropium and tiotropium have absolute oral bioavailability of only 2–3% in humans, well below the 20% threshold, due to poor gastrointestinal absorption and active intestinal secretion. Therefore the query is predicted to have low oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule; prediction relies on close quaternary ammonium tropane analogues.",
    "Dose, formulation, and food effects on absorption are not fully captured by the available records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

